-- DRAFT, NOT APPLIED. 3D sun view, third terrain level (detail) for the Faroe Islands: real foreground around the stand spots.
-- Written by tools/sun3d/faroes/build_detail_faroes.py. No laser survey exists there, so each box is:
--   path        heights = ArcticDEM v4.1 2 m cleaned into ground (sea flat at 0, lakes flat, the bumps under buildings removed)
--               with the agency's building outlines on it as upright flat-roofed blocks (the page's 16-bit format,
--               height = base_m + value * step_m)
--   mask_path   8-bit class mask: 0 ground, 2 building, 3 water (sea, lakes, mapped stream lines). No tree classes.
--   color_path  NEW: an aerial photo of the box, a square JPEG, north up, on exactly the box's lat / lng grid
--               (row 0 = north edge, linear in lat and lng like the heights), about 0.5 m a pixel (1 m in the 2 km boxes).
--               The page drapes it over the ground and the roofs; walls need a colour of their own.
-- Credit, wherever these are shown: Data from the Faroese Environment Agency, Umhvørvisstovan: Myndakort, Bygningar, Lendiskort, Topo (webservice, November 2026). Heights: ArcticDEM v4.1, Polar Geospatial Center (CC-BY-4.0).
--
-- Before applying: upload the files listed in upload.txt to bucket `terrain`.
alter table public.terrain_detail_regions add column if not exists color_path text, add column if not exists color_bytes integer;

on conflict (id) do nothing;

